<?php
session_start();
if (!isset($_SESSION['user_id']) || ($_SESSION['role'] ?? '') !== 'admin') { header('Location: ../login.php'); exit(); }
require_once '../config/db.php'; require_once '../includes/module_helpers.php';
$error=''; $message='';
if (!ensureCareerTables($conn)) $error='Could not prepare the careers table. Check database permissions.';
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_career']) && !$error) {
    $id=(int)($_POST['career_id']??0); $name=trim($_POST['career_name']??''); $description=trim($_POST['description']??''); $skills=trim($_POST['required_skills']??'');
    if ($name==='') $error='Career name is required.';
    else if ($id>0) { $stmt=$conn->prepare('UPDATE careers SET career_name=?,description=?,required_skills=? WHERE career_id=?'); $stmt->bind_param('sssi',$name,$description,$skills,$id); if($stmt->execute()) $message='Career updated.'; else $error='Could not update career.'; $stmt->close(); }
    else { $stmt=$conn->prepare('INSERT INTO careers (career_name,description,required_skills) VALUES (?,?,?)'); $stmt->bind_param('sss',$name,$description,$skills); if($stmt->execute()) $message='Career added.'; else $error='Could not add career.'; $stmt->close(); }
}
$edit=null; if(isset($_GET['edit'])) { $id=(int)$_GET['edit']; $stmt=$conn->prepare('SELECT * FROM careers WHERE career_id=?'); $stmt->bind_param('i',$id); $stmt->execute(); $edit=$stmt->get_result()->fetch_assoc(); $stmt->close(); }
$careers=$conn->query('SELECT * FROM careers ORDER BY career_name');
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Career Management</title><style>body{font:16px Arial;background:#f4f6fb;color:#172033;margin:0}.wrap{max-width:1050px;margin:32px auto;background:white;padding:26px;border-radius:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}input,textarea{display:block;width:100%;box-sizing:border-box;padding:10px;margin:8px 0 14px}textarea{min-height:90px}button{padding:10px 16px}article{padding:12px;border-bottom:1px solid #ddd}.note{padding:10px;background:#eef6ff}</style><link rel="stylesheet" href="../assets/cute-theme.css">
</head><body class="neon-app"><a class="admin-home-icon" href="dashboard.php" aria-label="Admin dashboard" title="Admin dashboard"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3.5 10 8.5-7 8.5 7"/><path d="M5.5 9v11h13V9M9 20v-6h6v6"/></svg></a><a href="../logout.php" style="position:fixed;top:18px;right:22px;background:#5633a3;color:white;padding:10px 16px;border-radius:6px;text-decoration:none;z-index:10">Logout</a><main class="wrap"><h1>Career Management</h1><p>Add careers and maintain each career's description and required skills (one skill per line).</p><?php foreach([$message,$error] as $n):if($n):?><p class="note"><?=e($n)?></p><?php endif;endforeach;?><div class="grid"><section><h2><?= $edit?'Edit career':'Add a career' ?></h2><form method="post"><input type="hidden" name="career_id" value="<?= (int)($edit['career_id']??0) ?>"><label>Career name<input name="career_name" maxlength="150" required value="<?=e($edit['career_name']??'')?>"></label><label>Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label>Required skills<textarea name="required_skills" placeholder="Communication&#10;Problem solving"><?=e($edit['required_skills']??'')?></textarea></label><button name="save_career" value="1">Save career</button><?php if($edit):?> <a href="careers.php">Cancel</a><?php endif;?></form></section><section><h2>Careers</h2><?php while($c=$careers->fetch_assoc()):?><article><h3><?=e($c['career_name'])?></h3><p><?=nl2br(e($c['description']))?></p><p><strong>Skills:</strong><br><?=nl2br(e($c['required_skills']))?></p><a href="?edit=<?=(int)$c['career_id']?>">Edit</a></article><?php endwhile;?></section></div></main></body></html>
